const posts = [];
const inputPosts = $input.first().json.posts;

for (const html of inputPosts) {
  let postId = null;
  // Ищем ID поста
  const footerMatch = html.match(/t\.me\/[^\/]+\/(\d+)/);
  if (footerMatch) postId = footerMatch[1];

  if (!postId) continue;

  // --- 1. ТЕКСТ (MARKDOWN) ---
  const textMatch = html.match(/<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/);
  let rawHtml = textMatch ? textMatch[1] : '';

  let text = rawHtml
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<b>(.*?)<\/b>/gi, '**$1**')
    .replace(/<strong>(.*?)<\/strong>/gi, '**$1**')
    .replace(/<i>(.*?)<\/i>/gi, '_$1_')
    .replace(/<em>(.*?)<\/em>/gi, '_$1_')
    .replace(/<a href="([^"]+)".*?>(.*?)<\/a>/gi, '[$2]($1)')
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/<[^>]+>/g, '') // Убираем остальные теги
    .trim();

  // Заголовок
  let title = '';
  if (text.length > 0) {
    title = text.length <= 100 ? text : text.substring(0, 100) + '...';
  }

  // Дата
  const dateMatch = html.match(/<time datetime="([^"]+)"/);
  let publishedAt = dateMatch ? dateMatch[1] : null;

  // --- 2. ПРОСМОТРЫ ---
  let views = 0;
  // Ищем внутри тега views или просто класс
  const viewsMatch = html.match(/<span class="tgme_widget_message_views"[^>]*>([\s\S]*?)<\/span>/);
  if (viewsMatch) {
    const rawViews = viewsMatch[1].replace(/<[^>]+>/g, '').trim(); // Чистим от тегов внутри
    if (rawViews.includes('K')) views = Math.round(parseFloat(rawViews.replace('K', '').replace(',', '.')) * 1000);
    else if (rawViews.includes('M')) views = Math.round(parseFloat(rawViews.replace('M', '').replace(',', '.')) * 1000000);
    else views = parseInt(rawViews.replace(/[^\d]/g, '')) || 0;
  }

  // --- 3. РЕАКЦИИ ---
  let totalReactions = 0;
  // Ищем все блоки реакций
  const reactionSpans = html.matchAll(/<span class="tgme_reaction[^"]*">([\s\S]*?)<\/span>/g);

  for (const match of reactionSpans) {
    const content = match[1]; // Внутренности реакции
    let count = 0;

    // Пытаемся найти число внутри (любое число, возможно с K/M)
    // Игнорируем html теги, берем только текст
    const cleanText = content.replace(/<[^>]+>/g, '').trim();
    const numberMatch = cleanText.match(/([\d.,]+[KM]?)$/); // Ищем число в конце строки

    if (numberMatch) {
       const s = numberMatch[1];
       if (s.includes('K')) count = Math.round(parseFloat(s.replace('K','').replace(',','.')) * 1000);
       else if (s.includes('M')) count = Math.round(parseFloat(s.replace('M','').replace(',','.')) * 1000000);
       else count = parseInt(s.replace(/[^\d]/g, '')) || 0;
    }
    totalReactions += count;
  }

  // --- 4. КАРТИНКИ ---
  const images = [];
  const imageMatches = html.matchAll(/background-image:\s*url\(['"]([^'"]+)['"]\)/g);
  for (const match of imageMatches) {
    const url = match[1];
    if (url.includes('telesco.pe') && !url.includes('telegram.org')) {
      images.push(url);
    }
  }

  // --- 5. РАСЧЕТ ER ---
  let er = 0;
  if (views > 0) {
    er = (totalReactions / views) * 100;
    er = Math.round(er * 100) / 100;
  }

  posts.push({
    post_id: postId,
    title: title,
    text: text,
    published_at: publishedAt,
    views: views,
    images: images,
    total_reactions: totalReactions,
    er: er
  });
}

// Дедупликация
const uniquePostsMap = new Map();
for (const post of posts) {
  if (!uniquePostsMap.has(post.post_id)) {
    uniquePostsMap.set(post.post_id, post);
  }
}
const uniquePosts = Array.from(uniquePostsMap.values());

return [{
  json: {
    posts: uniquePosts,
    channel_name: $('Set Initial Variables').item.json.channel_name
  }
}];

