parameters.jsCode:
const posts = $('Parse Posts').item.json.posts;

// Получаем переменные из Set Initial Variables
const channelName = $('Set Initial Variables').item.json.channel_name;
const currentIteration = $('Set Initial Variables').item.json.iteration || 0;
const maxIterations = $('Set Initial Variables').item.json.max_iterations || 50;
const previousTotal = $('Set Initial Variables').item.json.total_posts_collected || 0;

// Если постов нет - возвращаем метаданные с флагом остановки
if (!posts || posts.length === 0) {
  return [{
    json: {
      channel_name: channelName,
      oldest_post_id: "",
      iteration: currentIteration + 1,
      max_iterations: maxIterations,
      total_posts_collected: previousTotal,
      posts_in_batch: 0,
      continue_loop: false,
      message: "No posts found - stopping loop"
    }
  }];
}

// Сортируем посты по post_id (числовая сортировка)
const sortedPosts = posts.sort((a, b) => {
  const idA = parseInt(a.post_id);
  const idB = parseInt(b.post_id);
  return idA - idB;
});

// Берём ID самого старого (первого) поста
const oldestPostId = sortedPosts[0].post_id;
const postsCount = posts.length;
const newTotal = previousTotal + postsCount;

// Решаем продолжать ли цикл
const continueLoop = postsCount >= 5 && currentIteration < maxIterations;

// Возвращаем метаданные для управления циклом
return [{
  json: {
    channel_name: channelName,
    oldest_post_id: oldestPostId,
    iteration: currentIteration + 1,
    max_iterations: maxIterations,
    total_posts_collected: newTotal,
    posts_in_batch: postsCount,
    continue_loop: continueLoop,
    message: `Iteration ${currentIteration + 1}: Collected ${postsCount} posts. Total: ${newTotal}. ${continueLoop ? 'Continuing...' : 'Stopping.'}`
  }
}];

// Собираем все настройки в удобный объект
const settings = {};

const items = $input.all();

items.forEach(item => {
  const key = item.json.setting_key;
  const value = item.json.setting_value;
  settings[key] = value;
});

// Возвращаем один объект со всеми настройками
return [{
  json: {
    admin_chat_id: settings.admin_chat_id,
    days_before_ideas: settings.days_before_ideas,
    supabase_url: settings.supabase_url,
    default_channel_name: settings.default_channel_name
  }
}];
